import { defineQuery } from 'next-sanity'

/*
 * GROQ queries. Each projects Sanity documents into the front-end shapes in
 * src/content/types.ts. Types for every query are generated by `pnpm typegen`.
 */

const cta = /* groq */ `label, style, "href": select(linkType == "external" => url, internalPath)`
const navItem = /* groq */ `label, "href": select(linkType == "external" => url, internalPath)`
const image = /* groq */ `asset->{_id, url, metadata{lqip, dimensions{width, height}}}, crop, hotspot, alt, caption, treatment, overlayOpacity`
const hero = /* groq */ `eyebrow, headline, alternativeHeadlines, supportingText, primaryCta{${cta}}, secondaryCta{${cta}}, image{${image}}`
const textSection = /* groq */ `eyebrow, headline, body, cta{${cta}}`
const banner = /* groq */ `headline, body, primaryCta{${cta}}, secondaryCta{${cta}}`
const seo = /* groq */ `seo{title, description, noIndex, ogImage{${image}}}`
const crossLink = /* groq */ `crossLink{eyebrow, title, headline, cta{${cta}}}`
const projectSummary = /* groq */ `_id, title, "slug": slug.current, client, "category": category->{_id, title, "slug": slug.current}, coverImage{${image}}, overview`
const approvedProject = /* groq */ `_type == "project" && clientApproved == true && defined(slug.current)`

export const siteSettingsQuery = defineQuery(`*[_type == "siteSettings"][0]{
  siteName, tagline, description, footerStatement, brandLine, brandLineOptions,
  contactEmail, phone, officeAddress, location,
  social{linkedin, facebook, instagram, youtube}, socialHandle,
  seo{titleTemplate, description, ogImage{${image}}},
  logos{
    "horizontal": horizontal.asset->url, "vertical": vertical.asset->url,
    "symbol": symbol.asset->url, "mini": mini.asset->url,
    "bw": bw.asset->url, "bwInverted": bwInverted.asset->url
  }
}`)

export const navigationQuery = defineQuery(`*[_type == "navigation"][0]{
  main[]{${navItem}},
  headerCta{${cta}},
  footer{
    quickLinksHeading, quickLinks[]{${navItem}},
    divisionsHeading, divisions[]{${navItem}},
    contactHeading, socialHeading
  }
}`)

export const homePageQuery = defineQuery(`*[_type == "homePage"][0]{
  hero{${hero}},
  intro{${textSection}},
  divisions{eyebrow, headline, intro, items[]{key, number, title, headline, body, servicesLabel, services, cta{${cta}}}},
  approach{eyebrow, headline, body, processLabel, steps[]{title, description}, cta{${cta}}},
  clients{eyebrow, headline, body, sectorsLabel, sectors},
  featuredWork{eyebrow, headline, body, cta{${cta}}},
  closingCta{${banner}},
  ${seo}
}`)

export const featuredProjectsQuery = defineQuery(
  `*[${approvedProject} && featured == true] | order(date desc)[0...6]{${projectSummary}}`,
)

export const aboutPageQuery = defineQuery(`*[_type == "aboutPage"][0]{
  hero{${hero}},
  overview{${textSection}},
  vision{${textSection}},
  mission{${textSection}},
  philosophy{${textSection}},
  values{eyebrow, items[]{title, description}},
  approach{${textSection}},
  ${seo}
}`)

export const servicesPageQuery = defineQuery(`*[_type == "servicesPage"][0]{
  hero{${hero}},
  portfolio{eyebrow, navLabel},
  closing{statement, cta{${cta}}},
  ${seo}
}`)

export const servicesQuery = defineQuery(`*[_type == "service"] | order(order asc){
  _id, title, "slug": slug.current, order, summary, listLabel, items, "icon": icon.asset->url
}`)

export const eventsPageQuery = defineQuery(`*[_type == "eventsPage"][0]{
  hero{${hero}},
  whatWeDo{${textSection}},
  eventServices{eyebrow},
  capabilities{eyebrow, items},
  integrated{${textSection}},
  closingCta{${banner}},
  ${crossLink},
  ${seo}
}`)

export const eventServicesQuery = defineQuery(
  `*[_type == "eventService"] | order(order asc){_id, title, order, description}`,
)

export const mediaPageQuery = defineQuery(`*[_type == "mediaPage"][0]{
  hero{${hero}},
  sections[]{eyebrow, headline, body, listLabel, items},
  closingCta{${banner}},
  ${crossLink},
  ${seo}
}`)

export const ourWorkPageQuery = defineQuery(`*[_type == "ourWorkPage"][0]{
  hero{${hero}},
  categoriesEyebrow, allLabel,
  emptyState{headline, body},
  projectLabels{client, serviceCategory, overview, objective, approach, contribution, outcome, gallery, previous, next, backToWork},
  closingCta{${banner}},
  ${seo}
}`)

export const projectCategoriesQuery = defineQuery(
  `*[_type == "projectCategory" && defined(slug.current)] | order(order asc){_id, title, "slug": slug.current}`,
)

export const projectsQuery = defineQuery(
  `*[${approvedProject}] | order(coalesce(date, _createdAt) desc){${projectSummary}}`,
)

export const projectQuery = defineQuery(`*[${approvedProject} && slug.current == $slug][0]{
  ${projectSummary},
  division, date, objective, approach, contribution, outcome,
  gallery[]{
    _type, _key,
    _type == "brandImage" => {${image}},
    _type == "galleryVideo" => {url, title, caption}
  },
  ${seo}
}`)

export const projectSlugsQuery = defineQuery(
  `*[${approvedProject}] | order(coalesce(date, _createdAt) desc){"slug": slug.current, title, _updatedAt}`,
)

export const contactPageQuery = defineQuery(`*[_type == "contactPage"][0]{
  hero{${hero}},
  info{eyebrow, generalInquiriesLabel, phoneLabel, officeAddressLabel, locationLabel},
  form{
    headline,
    labels{fullName, organization, email, phone, service, description},
    servicePlaceholder, serviceOptions, submitLabel, responseNote, successMessage, errorMessage
  },
  closingStatement,
  ${seo}
}`)

/** Last-modified dates for the sitemap. */
export const sitemapQuery = defineQuery(`{
  "pages": *[_type in ["homePage", "aboutPage", "servicesPage", "eventsPage", "mediaPage", "ourWorkPage", "contactPage"]]{_type, _updatedAt},
  "projects": *[${approvedProject}]{"slug": slug.current, _updatedAt}
}`)
